exec((__import__('pathlib').Path(__file__).parent/'mulanhua_a.py').read_text(encoding='utf-8').split("B('01巧夺死光表'")[0])
B('38无价奇石',[
C('keke_volcano','柯克教授','柯克教授是四人火山探险团的发言者和主要行动主持者，与同名船长没有身份联系。他们准备多年，想在火山热压条件中寻找大颗钻石，既追求财富，也相信深入熔岩会创造科学史上的第一次。为了保密，他们把设备设计分交数国工厂，又持枪取回图样和信件、软禁查访者云五风，甚至拟抢赌场筹钱。木兰花指出付了费用也不能合法化持枪抢取，并以担保赊账提供另一条路，他们才道歉、放人、停止进一步犯罪。柯克后来坦白计划，面对生命价值的劝告仍狂热地称钻石永恒、人的生命短暂。他热情接待偷偷来的穆秀珍，遇到她悬挂火山口的险情，也会害怕，却努力用缓慢指令帮助她恢复操作，不能只写成毫无人情的逐利者。探险遭空袭，穆保护了营地，他向她致谢并邀其共同下到火山深处；温压骤增、机械手熔坏时，他立刻命令提升，没有坚持让人陪设备同毁。失去大钻石的梦想后，他先沮丧，继而承认准备不足、活着出来有幸运成分。最终发现新的放射性样品，获勋章奖金，欠款由所在国承担。他没有获得主动放射能力，也没有留下能无限进入熔岩的完好器械。','探险中生还，经检查轻微辐射伤无碍，获勋章奖金和费用偿付；隔热囊损坏，样品归有关机构研究。','年轻学者，谈计划时目光狂热，危机中声音也会颤抖；无稳定五官细写。','完成前所未有的火山探索并找到巨大钻石，以成果证明多年工作价值。','保密时容许违法手段，经指出可行替代后改正；实遇失控时仍求救撤退。','科学计划、隔热设备操作、现场指挥；早期团体持枪不证明每一次枪击都是他所为。',[(894,962,'科学家身份、计划和狂热'),(806,860,'共同违法逻辑被纠正'),(1214,1234,'危机安抚'),(1842,1858,'永恒钻石说'),(1994,2024,'任务与实验调整'),(2276,2340,'紧急撤回、反思、发现和终局')],[('重要研究需要保护机密','认为正常程序会暴露目标','可能合理化胁迫，遇可行合作方案仍能改正。'),('有人用生命风险反对计划','多年投入已变成自我价值中心','会以科学意义和持久成果反驳，显露执念。'),('同伴在不可逆危险边缘','自己仍能提供操作指引','尽力镇定逐步指导，不能保证成功。'),('实测超过设备安全范围','有撤回通道可用','优先提升撤退，事后重新承认模型不足。')],roles=['单书主角','阶段性对立者'],aliases=['柯克博士'],limits='隔热囊、机械手和吊运系统属探险工程，终局已损坏；小说温度叙述不作为现实物理数据，也不转移为人体耐热。早期四人蒙面行动不能逐一配对。'),
C('mengsi','孟斯','孟斯是四人探险团中的高个地质学家，也是熟练的直升机驾驶员。他以专业考察名义取得火山所在国的支持，军队帮助搬运设备并提供飞机，使不可能由四人徒手完成的工程得以推进。他与同伴共享保密和钻石计划，初期团队违法不能凭其后来救人抹去，不过蒙面行动未逐名对应，不能把每个持枪细节都安到他身上。穆秀珍加入后，他负责把穿笨重防热衣的两人吊近火山口；突发热气流使机身上冲，未扣紧的钩子险些令穆跌落，他也极度紧张，明确承认强烈摇晃时不能保证控制。穆借机械手勉强挂住钢缆后，他协同柯克将其移回安全位置。后来穆学会适应火山气流，他愿将最危险的近口飞行交她，自己参加安装，显示专业协作而非执守岗位。遭空袭后，他感谢穆的救命之举，主动让出首次随隔热囊下探的名额，把珍视的荣誉交给她。探索因高热高压中止，他主张写报告公布成果，发现异石时一度想徒手拿取，经柯克警告立即收手。终局生还、辐射伤检查无碍并受勋，专业能力仍受设备、气流及知识边界制约。','生还并获勋章，接受辐射检查后确认无碍；让出的下探位置由穆秀珍实际使用。','瘦长、高个的地质学者，工作时专注，感谢与兴奋表达直接。','完成地质探索，让团队首次深入火山的努力得到认可。','依专业判断分工，危险中承认操纵极限，感激时愿让出个人荣誉。','地质知识、直升机驾驶、吊运和设备装配；军用机与吊具须实际可用。',[(896,958,'地质身份与政府协助'),(1078,1144,'驾驶资格和风险说明'),(1190,1246,'热流失控与救援困难'),(1798,1812,'协同接回'),(1970,1994,'分工调整'),(2216,2256,'让出名额与吊运'),(2290,2340,'撤回、报告、异石及终局')],[('环境比预先估计恶劣','操纵余量已经不足','明确说明控制极限，要求配合而不保证万无一失。'),('队友在自己领域学得更合用','任务需要实际结果','愿交换岗位，不把专业身份当独占权。'),('别人救下团队和工作','有自己极珍惜的机会可分享','会以具体让利来致谢，而不止口头赞扬。')],roles=['单书主角','阶段性对立者'],scores={'physical':1,'energy':0,'scope':0,'sustain':2,'range':0,'combat':1},tier='纸',limits='直升机强风中会失稳，不能按飞行工具速度推算自身反应；没有其亲自空战战绩。'),
C('hangu','汉谷','汉谷是四位年轻科学家中的一员，参与准备火山高温探索。团队中有物理教授与研究原子量变化者，但原文没有把他的名字明确对应到其中哪项专长，卡片只能保留共同科学背景，不能替他补博士领域。早期他们为了保密采取抢取图样和限制云五风自由的办法，得到木兰花批评和融资帮助后转向公开合作；后来汉谷承担留守营地、通讯和设备操作，是能让前线继续工作的地面成员。空袭来到时，他把军方雷达与拦截困难及时报告给穆秀珍，亲眼看见她诱使敌机撞山，激动地迎接她着陆。发现她手臂满是碎玻璃伤，他扶她进屋、帮忙擦汗，并因敬佩亲吻她的手臂。穆仍想马上继续飞，他没有只称赞硬撑，而提出自己去接回柯克、孟斯，让她坐下做通讯；这既维持任务，也给伤者休息。机械手熔毁以后，他先发现残端夹着异石，听到可能放射性警告，取长钳和厚金属盒处理。终局四人与穆都因接近样品受轻微辐射伤，经检查无碍，获奖励。他的体贴和好奇有具体动作，却不是万能急救或辐射免疫，吻手等表达也不应在每个新场景中机械重演。','参与发现样品，轻微辐射伤经检查无碍，获勋章奖金；仍为探险团队成员。','年轻科学家；具体五官未定，感激时神情郑重，行动热切。','让探索顺利完成，实际照顾保护过团队的人。','遇危险及时传递信息，见伤者逞强便提出可维持任务的替代分工。','营地通讯、直升机接运、设备辅助和样品初步处理；具体学科身份未对应。',[(894,904,'四名科学家共同身份'),(2028,2046,'营地雷达消息'),(2170,2204,'目击、扶伤者与替飞'),(2290,2340,'开启受损囊、发现样品、受勋')],[('前线需要外部情报','自己掌握通讯台与军方消息','先传具体距离方向和限制，不假装能凭意志召来援军。'),('伤者坚持完成任务','自己能够替换其工作','提出岗位交换，让休息与任务同时成为可能。'),('意外残留物引起注意','尚未查明物性','先提醒别人检查，经风险提示后使用现有工具隔离。')],roles=['单书主角','阶段性对立者'],limits='不把全部学科、早期蒙面枪手动作或火山下探经历无差别分给四人；汉谷未随囊实际下到七百尺。',uncertainties=['汉谷属于两名物理教授还是原子量研究者，原文未逐名对应。']),
C('volcano_fourth_scientist','火山探险团第四名科学家','这名未具名科学家是柯克、孟斯、汉谷之外的第四位成员，属于固定四人探险团，不能另编姓名，也不能与三位同伴合成一个万能科学家。团队明确包括两位物理教授、一位研究原子量变化者和地质学家，除孟斯外未逐人对应学科，因此他的专门领域仍需保留不明。他参与多年筹备，最初赞同把设计委托分散到不同国家，通过抢取文件和软禁来保密；木兰花指出他们想以未来还钱为赌场抢劫辩护的错误，并提供赊造装备的途径后，团队取消计划、道歉和放人。他们在高热地带建立营地，操作记录仪对照爆发周期，协助运输、检查防热衣与隔热囊，任何一项都依赖真实器材和共同分工。穆秀珍承担飞行后，除留守的汉谷外，他与柯克、孟斯在火山顶安装并操纵下放设备；紧急提升使囊中两人生还。他参与检查受损器械和后来样品的发现，经历轻微辐射伤而未留下明确后遗症。终局获勋章及费用支援，却没有得到预期大钻石。他的个体描写有限，演绎应以团队合作、科学热情与曾合理化秘密行动的经历展开，不把未归属的台词和动作写成其独有战绩。','随团队完成探索并生还，接受辐射检查，获勋章；姓名与具体学科未给出。','年轻科学家，具体外貌与个人习惯未独立描写。','与同伴完成筹备多年的火山探索，并使研究获得实质成果。','依赖分工和专业记录；初期为保密让步于错误手段，获替代资源后可改正。','记录分析、仪器与吊放设备协作；不能独立拥有其他成员全部技能。',[(894,962,'固定四人构成及共同计划'),(806,860,'取消抢劫、改用合作'),(1938,1956,'记录仪和周期分析'),(1994,2024,'顶上分工'),(2276,2340,'救回、损坏与终局')],[('保密目标与合作程序冲突','资源不足而团队主张越界','可能随集体合理化错误，需要具体可行替代才能转向。'),('新记录符合研究模型','团队即将正式作业','据记录调整分工，但模型不能保证未来毫无变化。'),('同伴发出设备超限警报','自己在地面操作链上','按紧急需要协力提升撤回，而不为数据拖延。')],roles=['单书主角','阶段性对立者'],limits='固定第四名，非可无限复制的科学家群体；姓名和学科未明，能力只按协作中明确共同工作。',uncertainties=['部分团体动作无法逐名归属，保留为共同参与。']),
C('diamond_bald_director','钻石财团秃顶董事','这名约五十岁的秃顶董事由南非钻石财团派到本市，与胖董事同住蓝天酒店，寻找能杀死木兰花的人。财团误认木兰花主持火山寻钻计划，担心大量钻石出现将使垄断价格崩溃，他便把经济威胁变成对一个人的谋杀预算。他不熟悉本地江湖，只能通过郭老大招募，来人听见目标名字大多退却，所以木兰花化装成霍姓男子、自称能解决目标时，他急于相信。面对对方要求年度利润份额，他没有独立决定权，要和董事会联系；这种制度流程并没有阻止杀人计划，只决定能付多少。董事长另派的职业凶手突然潜入，他先惊恐，看到杀人工具更怕自己被误伤，却仍接受用其除掉漫天开价者，只要求别在酒店动手以免牵连。木兰花制住凶手后折返，告知可能供出雇主，他立刻从招募者变成想逃避司法的被威胁者，感谢提醒，准备离城。终局没有明确审判，也未证明真的退出整个财团。人物不是高阶战士，危险在能为利润出资、服从董事会并把暴力后果推远；胆小和参与谋杀并不矛盾。','刺客被捕后受揭露风险威慑，接受离城建议；实际离境及司法结局未明。','五十上下，头顶半秃，受惊时脸色灰白，讲话拘谨。','维护财团钻石收益，完成对误认的计划主持者的清除安排。','先讨价、请示，遇职业杀手和司法风险时害怕牵连自己。','财团交涉、委托与报酬协调；不具已证实个人武技。',[(1344,1380,'买凶背景及误判'),(1452,1508,'外貌、条件与董事会'),(1528,1554,'接待刺客并要求移出现场'),(1712,1738,'失败与离城建议')],[('市场利润受到潜在冲击','把计划错误归因于某个领头者','可能资助除掉个人，忽略研究不会随一人消失。'),('承包者开出超权限价码','自己仍需董事会授权','暂停成交并请示，不拥有无限资金。'),('所雇暴力可能留下现场关联','个人安全和刑责开始迫近','要求把行动移远，随后急于切断联系。')],roles=['反派'],limits='董事身份只产生有条件的经济渠道，不能让个人免伤或自动调动全部财团武装。'),
C('diamond_fat_director','钻石财团胖董事','胖董事与秃顶同僚代表南非钻石财团到本市，寻找杀手阻止他们误以为由木兰花主持的火山寻钻计划。他身材肥胖，面临棘手交易会擦额头的汗，外表与习惯都不同于同伴，原文没有给出姓名。两人悬出重金，却因女黑侠声名使本地杀手退缩，只能接受主动上门者的自我介绍。木兰花伪装的霍先生要求分取财团年度利润，他先说不可能，继而提出把一次报酬翻倍，以有限加价换回他熟悉的交易方式。进入内室，他仍怀疑此人能否对付木兰花；董事长聘来的真正刺客出现，他又从估价者变成被凶器吓住的人。他不反对杀掉外面的竞争承包者，却反对在自己入住的套房杀人，因为酒店柜台知道访客上门，连累很难摆脱。凶手被制服的消息传来，他想用职业道德安慰自己，盼受雇者不供出财团，这种道德观只保护雇主关系，并没有包含目标生命。终局面对泄露风险而失去继续招募的胆量，作品未写其受审。他适合呈现权势者如何一边惧怕暴力，一边以预算和免责要求让它发生，不能把富有直接换算为个人战斗力。','所聘凶手被捕后惊惧，受建议离城；最终法律处置未写。','肥胖、挺腹，紧张时额角沁汗并用手帕擦拭。','降低清除威胁的成本，维护财团利润并避免自身卷入刑责。','先用加价谈判，威胁变成切身时强调地点、证人和保密。','价格谈判、委托协调与商务掩护；无本人直接战斗证据。',[(1454,1488,'外貌及加价'),(1498,1508,'怀疑承包者'),(1534,1554,'害怕凶器及酒店关联'),(1720,1738,'供述忧虑和结局')],[('对方要求长期分利','自己更愿付一次成本','会提高一次价码以保住持续收益。'),('受雇者擅自扩张杀人范围','动手地点能追到自己','首先阻止现场牵连，未必阻止杀人本身。'),('执行者落网','雇主身份可能被说出','寄望其守职业约定，也准备撤离风险地。')],roles=['反派']),
C('buliezhi','布列治','布列治是钻石财团董事长，人物本人没有在木兰花面前现身，却通过有署名的介绍信和雇佣安排直接进入谋杀链。他所代表的既得利益担心火山研究带来大量钻石，冲破人为控制的价格，把木兰花误认成必须清除的主持者。财团两位董事在本市招募迟迟不成功，正准备就高额条件请示董事会，布列治已经从另一条渠道聘来职业凶手。杀手携信潜入套房，使两位代表确认其受董事长委托，而不是普通不请自来的竞争者。这说明他能够在下属谈判之外同时部署，也说明组织并没有完全共享信息：代表事先不知道新杀手已经上路，突然见面还要追问为何不先打电话。杀手不喜欢现代通讯的说辞，又暴露雇主对执行者个人习惯作了让步。木兰花最后制服刺客，借其可能供出布列治的名字威慑两名代表，买凶路线因而停止；原文没有确认董事长本人被逮捕。后来火山空袭被归于财团，但没有逐项展示布列治亲自下达的飞行命令，不能全算个人已证行动。终局的他是远距雇凶决策者，财富与董事长身份不构成肉身武力，更不赋予精准知晓一切研究秘密的能力。','受雇刺客被捕，姓名成为可能追查的雇主线索；本人后续司法与职位未明。','未直接出场，外貌无据；仅保留通过信件和受雇者传达的权力关系。','维护财团钻石利益，清除被误认为导致收益崩溃的关键人物。','在地方招募之外另雇职业杀手，愿意用组织资源替代亲自冒险。','高层委托、资金与信件授权；无个人武力或全知情报证据。',[(1362,1380,'财团动机与目标误判'),(1484,1488,'董事会决策链'),(1528,1554,'署名信与已聘刺客'),(1720,1738,'可能被供出的风险')],[('下属迟迟不能解决收益威胁','有另一路可用执行者','可能平行委托，不等地方谈判结束。'),('计划依赖擅长暴力的人','其个人习惯不合组织流程','会让步于效率，产生信息不同步。'),('雇佣关系可能进入警方证据链','身份隐藏已不可靠','面临停止、切割或继续加码的真实代价，不自动获得豁免。')],roles=['反派'],limits='未实际登场，行动限于有明确署名和雇佣关联的部分；财团后续全部行为不能自动逐项归其亲令。',confidence='medium'),
C('guo_diamond_boss','郭老大（钻石买凶中介）','郭老大在本市以正当商人面目活动，暗中影响数个犯罪组织，是警方和木兰花早已重视却缺少确证的对象。他在本书没有与女黑侠正面对谈，实际作用由线人花楷模带来的消息揭开：南非两家钻石矿的董事来到蓝天酒店，需要有人杀木兰花，先找的就是郭老大，再经他的渠道放出招募消息。这样一来，他把外来财团的金钱接上本地暴力市场，并不必亲自使用武器。来应征的人听见木兰花名字便退走，显示他的网络不能强迫每个亡命者接受不愿承担的风险，也不是一句话就能召来成功杀手。木兰花后来化装成霍人慧，借称郭先生介绍取得上楼机会，利用的正是中介身份在委托方眼中的可信度，并非郭真的认识这个化名。故事没有展示郭参与火山研究或获知全部科学内容，也没有证明他与财团主席直接联络。终局刺客被制、买凶路线受阻，郭本人未被明确逮捕，之前缺乏司法确证的问题仍然保留。这个人物的行为逻辑是以合法生意外衣维持地下联系，从危险交易中提供入口；不能因一句影响数个组织就把所有成员、武器和情报当他的自动装备。','买凶渠道被木兰花利用并阻断，郭本人未直接出场或被明确拘捕。','外貌未写；公开身份为商人，具体装束不得补作原作事实。','通过本地地下网络维持中介影响与交易地位。','以间接介绍和消息流通连接外来委托者，避免自己站到武力前线。','本地犯罪关系与招募中介；参与本案的证据主要为线人报告。',[(1324,1362,'线人身份、郭的掩护与招募链'),(1446,1450,'木借介绍身份进入酒店'),(1736,1738,'买凶路线受阻')],[('外来金主缺少本地暴力渠道','自己的介绍能被双方承认','把需求传入地下网络，保持中间位置。'),('目标声名使执行者退却','没有愿意接单的人','人脉也会遇到风险定价和拒绝，不能凭命令制造忠诚。'),('警方怀疑而证据不足','公开生意身份仍成立','依赖间接关系保持距离，但留下联系人线索。')],roles=['反派'],limits='主要依据线人报告，不能把未写的亲自杀人、幕后总指挥或其他同姓郭人物合并进来。',confidence='medium'),
C('diamond_old_woman_assassin','化装老妇的钻石财团刺客','这名职业刺客由布列治聘来，不愿使用现代枪械，自称偏爱无声夺命的旧式工具，但原文没有具体展示工具形状或致死原理，不能凭神秘口吻补出毒蛇、毒针或超自然武器。他携董事长来信潜入酒店内室，使两位财团代表吃惊，又把外面漫天开价的霍姓访客视为职业竞争者，主动提出免费除掉。为免牵连雇主，他接受出酒店再动手，自己伪装成迟缓老妇，打算利用不惹人注意的形象和电梯路线接近目标。木兰花最初确实误算他的移动，反成被监视者，后来重新推演路线，近看手部破绽并观察跟随，才确认伪装。刺客不知对面男子也是木兰花的化装，被枪口抵住腰际以后试图改用合作谈判，认为两名杀手共同对付女黑侠可分报酬，面对九一分成又不肯接受。木兰花用麻醉针将他制服，拖到僻静处后通知警方，雇佣身份于是成为威慑财团的证据入口。终局仍是活着的被拘者，没有完整实战证明其古式凶器威力。他擅长潜入、伪装和跟踪，但对同行身份与职业关系的判断会被反用。','被木兰花以麻醉针制服，交警方带走；凶器与后续审判未详细写出。','真容未披露；伪装为老态妇人，粗大的手成为近看破绽，真声阴冷。','按报酬杀人并排除竞争者，维护自己职业价值。','先隐蔽接近，被枪制住后谈合作，对过低分成仍反感。','潜入、跟踪、化装与未详旧式杀人工具；不能由自夸推定无条件必杀。',[(1528,1554,'雇佣、工具自述与杀人规则'),(1590,1672,'电梯追踪及化装破绽'),(1674,1710,'试探接近、谈判和被捕')],[('同一雇主正在谈另一执行者','可借排除对手增强自己价值','会主动扩张杀人提议，同时照顾雇主免被牵连的要求。'),('目标需要帮助弱者','伪装能降低警觉','以老妇求助接近，但外观和行为都可能露出细节。'),('被更直接的武器控制','对方被误认成同行','转谈分利求生，仍可能因报酬自尊错失退路。')],roles=['反派'],scores={'physical':2,'energy':0,'scope':1,'sustain':2,'range':0,'combat':3},tier='并',limits='旧式凶器仅被描述为可杀人，具体机制未给；无远程必杀或反麻醉能力。'),
C('volcano_attack_pilot','火山空袭战斗机驾驶员','这名未具名驾驶员驾驶没有国籍标志的草绿色战斗机，突袭火山探索地点，叙事将攻击归于钻石财团对研究的破坏。他选择的不是防务重点，来机速度使驻军来不及调空军，准备利用几次低空掠过摧毁火山口的设备，迫探险成为泡影。第一次观察飞行就显示熟练技术，面对穆秀珍用直升机突然射击，他迅速拉升，利用机速和武器优势转而追击。可是他不愿与直升机同归于尽，穆两次迎面逼近都迫使他改变航向；这种求生倾向不是怯懦到不会开枪，他随后远处开火击碎机舱玻璃，使穆左臂受伤、直升机下坠，几乎取得优势。追击到低空时，他以为对方失控，却遇直升机突然迎上，急忙避让，速度与贴近山体的位置反而限制了出路。他仍尝试以高超操作拉起，机腹擦过山岩，随后爆炸，整机毁灭。终局恢复部署若需要飞机必须明示，不能将双机枪和飞行速度算成裸身能力，也不能因对手称世界第一流就断言在所有空域都无人能敌。他的危险来自装备、先手和驾驶经验，失败来自目标地形及不愿碰撞的选择被准确利用。','战斗机低空避撞后擦山爆炸，驾驶员随飞机死亡。','未见驾驶员外貌；可见载具为无国籍标志的草绿色旧式小型战斗机。','摧毁火山探险设备，完成财团的破坏任务并自行返航。','先利用空袭突防，受拦截后依机速火力追击，但避开同归于尽的正撞。','特定战斗机驾驶、双机枪攻击与低空飞行；装备不可与本人肉体混同。',[(2028,2064,'突袭、任务与飞行技术'),(2070,2124,'交战、避撞及反击'),(2126,2164,'击伤对方与撞山终局')],[('目标没有及时空中防御','已有适用飞机与进攻航线','抢时间直扑设备，不与地面人员纠缠。'),('较弱载具正面逼撞','自己仍想完成任务后生还','利用速度避让，暴露可被预测的回避方向。'),('对手似乎失控下坠','快速追击能完成击毁','可能过深追入地形限制，经验也不能抹去转向余量。')],roles=['反派'],scores={'physical':2,'energy':0,'scope':2,'sustain':2,'range':3,'combat':3},tier='并',revive=True,limits='评级为明确配置该战斗机的场景；裸身无超常表现。飞机型号未给出，不能补武器口径、弹药量或绝对速度。',deployment='回溯恢复最后可行动驾驶员；若按本档评级部署，另配本书同等旧式战斗机及有限弹药，不把飞机融入身体。')
],cast=['mu_lanhua','mu_xiuzhen','gao_xiang','annie','yun_sifeng','yun_wufeng'],excluded=[{'name':'裴隆律师及其家人','reason':'一次性委托与被胁迫询问的配角，未参与科学家违法计划；不因守职业秘密标为反派。'},{'name':'花楷模／花蛤蟆','reason':'本书一次线人，过去被木兰花抓捕只是概述，未检到其他书实际出场；不据背景一句扩成跨书角色。'},{'name':'李总编辑、驻军官员及服务人员','reason':'一次性协助、传讯与场景角色，无独立主角线。'}],notes=['38科学家柯克与08船长、卫036船长不合并；四名科学家中两名具名者之外仅第四名未具名，学科不能凭顺序硬配。','早期科学家仍属阶段性对立者，后道歉放人、取消抢劫，结局获科学成果不抹去违法手段。','穆秀珍机枪多次未中，胜靠迫使敌机低空避撞后擦山；左臂为玻璃伤，非防弹。隔热囊损坏和轻辐射经检查无碍均不是人体抗性。','木兰花与穆以家庭安全威胁律师，不能将核心卡写为绝不胁迫；结尾云四风正式求婚、穆同意下月结婚。'])
(P/'mulanhua_aj.draft.json').write_text(json.dumps(books,ensure_ascii=False,indent=2),encoding='utf-8')
